const D = { energy:.6, scale:1, density:.5, speed:1, hue:38, x:.5, y:.5, trail:.55, anno:.65, style:'film', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const T2 = Math.PI*2;
const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const AL = cl(P.alpha,20,100)/100;
const H = ((P.hue%360)+360)%360;
const sty = P.style;
const anno = cl(P.anno,0,1);
const NRG = cl(P.energy,0,1);
const TRL = cl(P.trail,0,1);

function pal(){
  if (sty==='cyanotype') return { g:[214,74,18], cell:[212,60,25], bar:[200,6,99], pin:[196,20,92], loc:[186,46,74], head:[46,68,98], ctr:[196,36,80], anno:[200,10,90], grain:34, add:false, wash:[196,22,80] };
  if (sty==='engraving') return { g:[38,18,72],  cell:[36,14,64], bar:[28,38,11], pin:[28,30,22], loc:[24,44,34], head:[6,72,42], ctr:[8,62,42], anno:[28,42,14], grain:32, add:false, wash:[44,26,96] };
  if (sty==='ghost')     return { g:[236,60,8],  cell:[232,50,13], bar:[H,30,96], pin:[H,14,100], loc:[H+150,58,70], head:[H,72,100], ctr:[12,70,58], anno:[H,16,84], grain:16, add:true,  wash:[H,44,60] };
  if (sty==='kinematic') return { g:[204,40,8],  cell:[202,44,13], bar:[186,60,86], pin:[186,26,96], loc:[52,66,88], head:[340,74,94], ctr:[10,70,66], anno:[52,54,86], grain:14, add:false, wash:[188,42,58] };
  return { g:[H,16,20], cell:[H,12,27], bar:[H,4,94], pin:[H,6,86], loc:[H,44,66], head:[H+22,72,96], ctr:[10,66,62], anno:[H,6,88], grain:28, add:false, wash:[H,12,80] };
}
const C = pal();
const sc = (c,a) => { stroke(((c[0]%360)+360)%360, c[1], c[2], a*AL); };
const fc = (c,a) => { fill(((c[0]%360)+360)%360, c[1], c[2], a*AL); };

// ---- real-time crank accumulator: never re-phases -----------------------------
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
const wob = 1 + .22*Math.sin(K.t*.127) + .14*Math.sin(K.t*.311+1.4) + .08*Math.sin(K.t*.739+2.7);
S.th = (S.th||0) + dt * wob * P.speed * (.55 + 1.5*NRG) * (.6 + .7*K.intensity);
const drx = .9*Math.sin(K.t*.139) + .5*Math.sin(K.t*.297+1.7) + .32*Math.sin(K.t*.463);
const dry = .8*Math.sin(K.t*.111+2.1) + .45*Math.sin(K.t*.253+.6) + .28*Math.sin(K.t*.611+1.9);
S.bs = (S.bs||0)*.84 + (A.bass||0)*.16;
const glow = (.42+.58*NRG)*(.55+.5*K.intensity) + S.bs*.3;

// ---- four-bar vector-loop solve (circle intersection) -------------------------
function solve(m, th2){
  const ax = Math.cos(th2)*m.a, ay = Math.sin(th2)*m.a;
  const dx = m.d - ax, dy = -ay;
  const L = Math.hypot(dx,dy);
  if (L > m.b + m.c || L < Math.abs(m.b - m.c) || L < 1e-6) return null;
  const q = (m.b*m.b - m.c*m.c + L*L)/(2*L);
  const hh = m.b*m.b - q*q;
  const h = Math.sqrt(hh < 0 ? 0 : hh);
  const mx = ax + q*dx/L, my = ay + q*dy/L;
  const bx = mx + m.br*h*(-dy)/L, by = my + m.br*h*(dx)/L;
  const th3 = Math.atan2(by-ay, bx-ax);
  const px = ax + Math.cos(th3)*m.px - Math.sin(th3)*m.py;
  const py = ay + Math.sin(th3)*m.px + Math.cos(th3)*m.py;
  // transmission angle at B, between coupler BA and rocker BO4
  const v1x=ax-bx, v1y=ay-by, v2x=m.d-bx, v2y=-by;
  const mu = Math.acos(cl((v1x*v2x+v1y*v2y)/(Math.hypot(v1x,v1y)*Math.hypot(v2x,v2y)+1e-9),-1,1));
  return { ax, ay, bx, by, px, py, th3, mu };
}

// ---- Grashof crank-rocker generator + coupler-curve locus ---------------------
function makeMech(sf){
  for (let tr=0; tr<48; tr++){
    const g = k => fr(sf*17.31 + tr*3.907 + k*1.61);
    const d = 1;
    const a = .15 + g(1)*.15;
    const b = .68 + g(2)*.50;
    const c = .55 + g(3)*.48;
    const arr = [a,b,c,d];
    let s = arr[0], l = arr[0];
    for (let i=1;i<4;i++){ if (arr[i]<s) s=arr[i]; if (arr[i]>l) l=arr[i]; }
    if (s !== a) continue;
    if (s + l > (a+b+c+d) - s - l) continue;            // Grashof
    const m = { a, b, c, d, px:(.12+g(4)*.9)*b, py:(g(5)-.5)*1.6*b, br: g(6)<.5?-1:1 };
    const loc = []; let ok = true, mnmu = 9;
    let x0=9, x1=-9, y0=9, y1=-9;
    const put = (x,y) => { if (x<x0)x0=x; if (x>x1)x1=x; if (y<y0)y0=y; if (y>y1)y1=y; };
    for (let i=0;i<256;i++){
      const r = solve(m, i/256*T2);
      if (!r){ ok = false; break; }
      loc.push(r.px, r.py); put(r.px,r.py); put(r.ax,r.ay); put(r.bx,r.by);
      if (r.mu < mnmu) mnmu = r.mu;
    }
    if (!ok) continue;
    if (mnmu < .18) continue;                            // reject near-toggle junk
    put(0,0); put(d,0);
    m.loc = loc; m.mu = mnmu; m.bb = [x0,y0,x1,y1];
    m.tag = (mnmu > .62 ? 'CRANK-ROCKER' : 'CRANK-ROCKER*');
    return m;
  }
  const m = { a:.22, b:.95, c:.75, d:1, px:.62, py:.46, br:1 };
  const loc=[]; let x0=9,x1=-9,y0=9,y1=-9;
  for (let i=0;i<256;i++){ const r=solve(m,i/256*T2); if(!r){loc.push(0,0); continue;}
    loc.push(r.px,r.py);
    if(r.px<x0)x0=r.px; if(r.px>x1)x1=r.px; if(r.py<y0)y0=r.py; if(r.py>y1)y1=r.py; }
  if (x0>0) x0=0; if (x1<1) x1=1; if (y0>0) y0=0; if (y1<0) y1=0;
  m.loc=loc; m.mu=.7; m.bb=[x0,y0,x1,y1]; m.tag='CRANK-ROCKER';
  return m;
}

// ---- mechanism pool ----------------------------------------------------------
const npool = Math.round(3 + cl(P.density,0,1)*11);
if (S.pool == null || S.pkey !== sd+'|'+npool){
  S.pkey = sd+'|'+npool; S.gen = 0; S.pool = [];
  for (let i=0;i<npool;i++) S.pool.push({ m: makeMech(i+1), born: K.t - 9, rate: .55 + fr(i*7.7+31)*1.05, fig: i+1 });
}
// dramaturgy: every section the plate re-drafts ONE figure, and it draws itself in
if (S.lastSec == null || S.lastSec !== (K.section|0)){
  S.lastSec = K.section|0; S.gen = (S.gen||0) + 1;
  const idx = ((K.section|0)*7 + 13 + S.gen) % S.pool.length;
  const e = S.pool[idx];
  e.m = makeMech(100 + S.gen*13 + idx); e.born = K.t; e.fig = (e.fig||1) + S.pool.length;
  e.rate = .55 + fr(S.gen*3.1 + idx*7.7 + 31)*1.05;
}
for (let i=0;i<S.pool.length;i++){ if (S.pool[i].born > K.t) S.pool[i].born = K.t; }

// ---- cached plate texture ----------------------------------------------------
const gkey = sd+'|'+sty+'|'+width+'x'+height;
if (!S.gr || S.gkey !== gkey){
  if (S.gr && S.gr.remove) S.gr.remove();
  const gw=170, gh=Math.max(60, Math.round(170*height/Math.max(1,width)));
  const g = createGraphics(gw,gh); g.loadPixels();
  for (let y=0;y<gh;y++) for (let x=0;x<gw;x++){
    const v = cl(255*(.44 + .32*fr(Math.floor(x/8)*13.71+Math.floor(y/8)*7.33+3.1) + .16*fr(Math.floor(x/3)*3.17+Math.floor(y/3)*11.9+8.7) + .08*fr(x*1.13+y*3.31+1.7)),0,255);
    const j=(y*gw+x)*4; g.pixels[j]=v; g.pixels[j+1]=v; g.pixels[j+2]=v; g.pixels[j+3]=255;
  }
  g.updatePixels(); S.gr = g; S.gkey = gkey;
}

// ---- ground + texture --------------------------------------------------------
noStroke(); fill(C.g[0],C.g[1],C.g[2],100); rect(0,0,width,height);
push(); blendMode(MULTIPLY); tint(0,0,100,C.grain); image(S.gr,0,0,width,height); pop();
blendMode(BLEND); noTint();

// wandering raking wash
const wx = width*(.5 + .30*Math.sin(K.t*.073)), wy = height*(.5 + .25*Math.sin(K.t*.101+1.2));
push(); blendMode(SCREEN); noStroke();
for (let i=5;i>=1;i--){ fill(C.wash[0],C.wash[1],C.wash[2],(2.0+1.8*glow)*AL); const rw=u*(.32+i*.20); ellipse(wx,wy,rw*2,rw*1.7); }
pop(); blendMode(BLEND);

// ---- grid of figures (absolute-indexed so P.scale is a true plate zoom) -------
const cw = u*.34*cl(P.scale,.4,2.4), ch = cw*.80;
const ox = cl(P.x,.15,.85)*width  + u*.014*NRG*drx - cw*.5;
const oy = cl(P.y,.15,.85)*height + u*.012*NRG*dry - ch*.5;
const ci0 = Math.floor((0-ox)/cw), ci1 = Math.ceil((width-ox)/cw);
const ri0 = Math.floor((0-oy)/ch), ri1 = Math.ceil((height-oy)/ch);
const kin = (sty==='kinematic');
if (C.add) blendMode(ADD);

function pivotSym(x,y,r){
  sc(C.bar, 86); strokeWeight(Math.max(.6,u*.0015)); noFill();
  triangle(x, y, x-r*1.5, y+r*2.4, x+r*1.5, y+r*2.4);
  sc(C.ctr, 62); strokeWeight(Math.max(.4,u*.0008));
  for (let i=-3;i<=3;i++) line(x+i*r*.62, y+r*2.4, x+i*r*.62 - r*.55, y+r*3.1);
  line(x-r*2.0, y+r*2.4, x+r*2.0, y+r*2.4);
  noStroke(); fc(C.g, 90); ellipse(x,y,r*1.0,r*1.0);
  sc(C.bar, 92); noFill(); strokeWeight(Math.max(.5,u*.0012)); ellipse(x,y,r*1.0,r*1.0);
}

let figCount = 0, annoN = 0;
for (let ri=ri0; ri<=ri1; ri++) for (let ci=ci0; ci<=ci1; ci++){
  const cellX = ox + ci*cw, cellY = oy + ri*ch;
  if (cellX > width || cellY > height || cellX+cw < 0 || cellY+ch < 0) continue;
  if (figCount++ > 44) break;
  const pi = (((ci*7 + ri*13) % S.pool.length) + S.pool.length) % S.pool.length;
  const e = S.pool[pi], m = e.m;
  const grow = cl((K.t - e.born)/2.6, 0, 1);

  // cell frame
  noStroke(); fc(C.cell, C.add? 10 : 34);
  rect(cellX+cw*.035, cellY+ch*.035, cw*.93, ch*.93);
  noFill(); sc(C.anno, 22+26*anno); strokeWeight(Math.max(.5,u*.0009));
  rect(cellX+cw*.035, cellY+ch*.035, cw*.93, ch*.93);

  // fit the mechanism into the cell
  const bw = m.bb[2]-m.bb[0], bh = m.bb[3]-m.bb[1];
  const fs = Math.min(cw*.74/Math.max(.2,bw), ch*.62/Math.max(.2,bh));
  const gx = cellX + cw*.5 - (m.bb[0]+bw*.5)*fs;
  const gy = cellY + ch*.52 - (m.bb[1]+bh*.5)*fs;
  const X = v => gx + v*fs, Y = v => gy + v*fs;

  const th2 = S.th * e.rate + pi*1.7;
  const r = solve(m, th2) || solve(m, 0);
  if (!r) continue;

  // ground centreline
  sc(C.ctr, 30+26*anno); strokeWeight(Math.max(.4,u*.0008));
  const gl = m.d*fs*.34;
  for (let s2=-gl; s2 < m.d*fs+gl; s2 += fs*.09) line(X(0)+s2, Y(0), X(0)+s2+fs*.055, Y(0));

  // coupler-curve locus (chain line), draws itself in after a re-draft
  const np2 = m.loc.length/2;
  const lim = Math.floor(np2*grow);
  sc(C.loc, (34+40*anno)*(.5+.5*grow)); strokeWeight(Math.max(.5, u*.0011*(.7+.7*NRG))); noFill();
  const stp = fs < u*.14 ? 3 : 2;
  beginShape();
  for (let i=0;i<lim;i+=stp) vertex(X(m.loc[i*2]), Y(m.loc[i*2+1]));
  endShape(lim >= np2 ? CLOSE : undefined);

  // persistent bright head along the locus — the pen that is drawing it
  const hi = Math.floor((((th2/T2)%1)+1)%1 * np2);
  const hl = Math.round(np2*(.06+.22*TRL));
  strokeWeight(Math.max(.7, u*.0022*(.6+.8*NRG)));
  for (let i=0;i<hl;i++){
    const j0 = (hi-i+np2*2)%np2, j1 = (hi-i-1+np2*2)%np2;
    sc(C.head, (86 - 84*(i/hl)) * (.4+.6*glow) * grow);
    line(X(m.loc[j0*2]), Y(m.loc[j0*2+1]), X(m.loc[j1*2]), Y(m.loc[j1*2+1]));
  }

  if (!kin){
    // bars: crank heavy, coupler as a rigid triangle, rocker heavy
    const lw = Math.max(.9, u*.0030*(.6+.8*NRG)) * cl(fs/(u*.30),.5,1.5);
    sc(C.bar, 92); strokeWeight(lw); noFill();
    line(X(0),Y(0), X(r.ax),Y(r.ay));                       // crank
    line(X(m.d),Y(0), X(r.bx),Y(r.by));                     // rocker
    // coupler triangle A-B-P
    noStroke(); fc(C.bar, C.add? 12 : 20);
    triangle(X(r.ax),Y(r.ay), X(r.bx),Y(r.by), X(r.px),Y(r.py));
    noFill(); sc(C.bar, 92); strokeWeight(lw);
    triangle(X(r.ax),Y(r.ay), X(r.bx),Y(r.by), X(r.px),Y(r.py));
    // pins
    const pr = Math.max(1.6, fs*.032);
    noStroke(); fc(C.g, C.add?26:92);
    ellipse(X(r.ax),Y(r.ay),pr*2,pr*2); ellipse(X(r.bx),Y(r.by),pr*2,pr*2);
    noFill(); sc(C.pin, 96); strokeWeight(Math.max(.5,lw*.55));
    ellipse(X(r.ax),Y(r.ay),pr*2,pr*2); ellipse(X(r.bx),Y(r.by),pr*2,pr*2);
    pivotSym(X(0),Y(0),pr*1.15); pivotSym(X(m.d),Y(0),pr*1.15);
    // coupler point
    noStroke(); fc(C.head, 96*(.5+.5*glow)); ellipse(X(r.px),Y(r.py), pr*1.7, pr*1.7);
  } else {
    // KINEMATIC: bars dissolve — pivots, coupler point, velocity & acceleration vectors
    const dth = .012;
    const r1 = solve(m, th2+dth), r2 = solve(m, th2-dth);
    if (r1 && r2){
      const vx=(r1.px-r2.px)/(2*dth), vy=(r1.py-r2.py)/(2*dth);
      const axx=(r1.px-2*r.px+r2.px)/(dth*dth), ayy=(r1.py-2*r.py+r2.py)/(dth*dth);
      const arrow = (x,y,dx2,dy2,col,k2) => {
        const ex2=x+dx2*k2, ey2=y+dy2*k2, an=Math.atan2(ey2-y,ex2-x), hd=fs*.045;
        sc(col, 88); strokeWeight(Math.max(.7,u*.0018)); line(x,y,ex2,ey2);
        line(ex2,ey2, ex2-Math.cos(an-.4)*hd, ey2-Math.sin(an-.4)*hd);
        line(ex2,ey2, ex2-Math.cos(an+.4)*hd, ey2-Math.sin(an+.4)*hd);
      };
      arrow(X(r.px),Y(r.py), vx*fs, vy*fs, C.head, .30);
      arrow(X(r.px),Y(r.py), axx*fs, ayy*fs, C.ctr, .028);
    }
    sc(C.bar, 44); strokeWeight(Math.max(.4,u*.0009));
    line(X(0),Y(0),X(r.ax),Y(r.ay)); line(X(m.d),Y(0),X(r.bx),Y(r.by)); line(X(r.ax),Y(r.ay),X(r.bx),Y(r.by));
    noStroke();
    for (const q2 of [[0,0],[m.d,0],[r.ax,r.ay],[r.bx,r.by]]){ fc(C.pin, 92); ellipse(X(q2[0]),Y(q2[1]), fs*.026, fs*.026); }
    fc(C.head, 98); ellipse(X(r.px),Y(r.py), fs*.040, fs*.040);
  }

  // per-figure annotation
  if (anno > .12 && cw > u*.17 && annoN < 20){
    annoN++;
    noStroke(); textFont('monospace'); textAlign(LEFT, TOP);
    textSize(Math.max(6, cw*.042));
    fc(C.anno, 62+34*anno);
    text('FIG. '+e.fig, cellX+cw*.062, cellY+ch*.058);
    textAlign(LEFT, BOTTOM);
    fc(C.anno, 46+30*anno);
    text('a'+m.a.toFixed(2)+' b'+m.b.toFixed(2)+' c'+m.c.toFixed(2)+' d1.00', cellX+cw*.062, cellY+ch*.955);
    if (cw > u*.29){
      textAlign(RIGHT, TOP); fc(C.anno, 62+34*anno);
      text('mu '+(r.mu*57.2958).toFixed(0)+' deg', cellX+cw*.93, cellY+ch*.058);
      textAlign(RIGHT, BOTTOM); fc(C.anno, 46+30*anno);
      text(m.tag, cellX+cw*.93, cellY+ch*.955);
    }
  }
}
blendMode(BLEND);

// ---- sheet border + title block ---------------------------------------------
const mgn = u*.028;
noFill(); sc(C.anno, 46+24*anno); strokeWeight(Math.max(.8,u*.0022));
rect(mgn, mgn, width-mgn*2, height-mgn*2);
sc(C.anno, 24+16*anno); strokeWeight(Math.max(.5,u*.0009));
rect(mgn*1.7, mgn*1.7, width-mgn*3.4, height-mgn*3.4);
if (anno > .08){
  textFont('monospace'); textAlign(RIGHT, CENTER); noStroke();
  const ts = Math.max(7, u*.0135); textSize(ts);
  const bx = width-mgn*2.0, by = height-mgn*2.0;
  fc(C.cell, C.add?30:84); rect(bx-u*.31, by-u*.052, u*.31, u*.052);
  noFill(); sc(C.anno, 62); strokeWeight(Math.max(.5,u*.0012)); rect(bx-u*.31, by-u*.052, u*.31, u*.052);
  line(bx-u*.31, by-u*.026, bx, by-u*.026);
  noStroke(); fc(C.anno, 90);
  text('PLANAR FOUR-BAR MECHANISMS - COUPLER LOCI', bx-u*.012, by-u*.039);
  text('GRASHOF s+l <= p+q   PLATE '+((S.gen||0)+1)+'   SEED '+sd, bx-u*.012, by-u*.013);
  textAlign(LEFT, CENTER); fc(C.anno, 66);
  text('theta2 '+(((S.th*57.2958)%360+360)%360).toFixed(1)+' deg', mgn*2.2, mgn*2.3);
}
blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
